// Turn the facts into alerts, or into nothing.
//
// docs/workflows.md: "An agent that silently stops running is the failure this
// exists to catch." Silence is not observable on its own - an agent with no runs
// and no work to do is healthy. So every idleness check is paired with evidence
// that there WAS work: a queue with something in it, old enough that a run
// should already have happened.
//
// Thresholds are read from the environment with defaults here, so a missing
// variable degrades to a sensible value instead of to NaN.

function num(value, fallback) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

const ERROR_RATE = num($env.HEALTH_ERROR_RATE_THRESHOLD, 0.25);
const MIN_RUNS = num($env.HEALTH_ERROR_RATE_MIN_RUNS, 3);
const STALLED_HOURS = num($env.HEALTH_STALLED_QUEUE_HOURS, 6);
const STUCK_MINUTES = num($env.HEALTH_STUCK_RUN_MINUTES, 15);

const facts = $('Collect Health').first().json ?? {};
const ollama = $input.first().json ?? {};

const alerts = [];
function raise(key, priority, title, body, payload) {
  alerts.push({ dedup_key: key, priority, title, body, payload: payload ?? {} });
}

function ageHours(ts) {
  if (!ts) return 0;
  return (Date.now() - new Date(ts).getTime()) / 3600000;
}

// --- Ollama ---------------------------------------------------------------
// The HTTP node continues on error, so an unreachable Ollama arrives as an item
// with an error rather than as a failed execution. That matters: a failed
// execution would hand this to WF-99 and no health alert would ever be written.
const models = Array.isArray(ollama.models) ? ollama.models : null;
if (models === null) {
  const reason = ollama.error
    ? (typeof ollama.error === 'string' ? ollama.error : (ollama.error.message ?? 'request failed'))
    : 'no model list in response';
  raise(
    'agent_health:ollama_unreachable',
    'immediate',
    'Ollama unreachable',
    'Ollama did not answer /api/tags: ' + reason +
      '\nEvery agent in the pipeline runs on it, so research, scoring and outreach are all stopped.',
    { check: 'ollama', reason },
  );
} else if (models.length === 0) {
  raise(
    'agent_health:ollama_no_models',
    'immediate',
    'Ollama has no models',
    'Ollama answered but reports zero installed models. Nothing can run until one is pulled.',
    { check: 'ollama', models: 0 },
  );
}

// --- Runs stuck at 'running' ----------------------------------------------
const stuckRuns = num(facts.stuck_runs, 0);
if (stuckRuns > 0) {
  const detail = Array.isArray(facts.stuck_detail) ? facts.stuck_detail : [];
  const lines = detail.slice(0, 5).map((r) => '- ' + r.agent + ' run ' + r.run_id + ', ' + r.minutes + ' min');
  raise(
    'agent_health:stuck_runs',
    'immediate',
    stuckRuns + ' agent run(s) stuck',
    stuckRuns + ' agent_runs row(s) have been at status=running for over ' + STUCK_MINUTES +
      ' minutes.\nA run that never closes means the workflow died without WF-99 closing it,' +
      ' and it holds the claim on its company.\n' + lines.join('\n'),
    { check: 'stuck_runs', count: stuckRuns, detail: detail.slice(0, 20) },
  );
}

// --- Error rate per agent --------------------------------------------------
const agents = Array.isArray(facts.agents) ? facts.agents : [];
for (const a of agents) {
  const runs = num(a.runs_24h, 0);
  const failed = num(a.failed, 0);
  if (runs < MIN_RUNS) continue; // Too few runs for a rate to mean anything.
  const rate = failed / runs;
  if (rate > ERROR_RATE) {
    raise(
      'agent_health:error_rate:' + a.agent,
      'immediate',
      'Agent "' + a.agent + '" failing',
      failed + ' of ' + runs + ' ' + a.agent + ' runs in the last 24h failed (' +
        Math.round(rate * 100) + '%, threshold ' + Math.round(ERROR_RATE * 100) + '%).' +
        '\nLast run: ' + (a.last_run_at ?? 'never'),
      { check: 'error_rate', agent: a.agent, runs_24h: runs, failed, rate: Number(rate.toFixed(3)) },
    );
  }
}

// --- Work waiting with nobody working on it --------------------------------
const byAgent = new Map(agents.map((a) => [a.agent, a]));
const stages = [
  { agent: 'research', pending: num(facts.research_pending, 0), oldest: facts.research_oldest,
    queue: "companies at status='new'" },
  { agent: 'scoring', pending: num(facts.scoring_pending, 0), oldest: facts.scoring_oldest,
    queue: "companies at status='researched'" },
  { agent: 'outreach', pending: num(facts.outreach_pending, 0), oldest: facts.outreach_oldest,
    queue: "leads at status='new' above OUTREACH_MIN_SCORE" },
];

for (const stage of stages) {
  if (stage.pending === 0) continue;
  const waited = ageHours(stage.oldest);
  if (waited < STALLED_HOURS) continue;
  const runs = num(byAgent.get(stage.agent)?.runs_24h, 0);
  if (runs > 0) continue; // It is running; a backlog alone is not a fault.
  raise(
    'agent_health:idle_agent:' + stage.agent,
    'normal',
    'Agent "' + stage.agent + '" has not run',
    stage.pending + ' item(s) are waiting in ' + stage.queue + ', the oldest for ' +
      Math.round(waited) + 'h, and the ' + stage.agent + ' agent has not run once in 24 hours.' +
      '\nThe usual cause is the workflow not being active in n8n.',
    { check: 'idle_agent', agent: stage.agent, pending: stage.pending, waited_hours: Math.round(waited) },
  );
}

// --- Companies abandoned mid-research --------------------------------------
const orphaned = num(facts.orphaned_researching, 0);
if (orphaned > 0) {
  raise(
    'agent_health:orphaned_researching',
    'normal',
    orphaned + ' company(ies) stuck researching',
    orphaned + " company(ies) have been at status='researching' long enough that no live run" +
      ' can still own them. They are claimed and will never be picked up again until the status' +
      " is put back to 'new'.",
    { check: 'orphaned_researching', count: orphaned },
  );
}

// --- The notifier itself ---------------------------------------------------
// Nothing watches the watcher, which docs/error-handling.md names as a gap.
// This is the closest honest check: alerts that were queued and never left.
const undeliverable = num(facts.undeliverable, 0);
if (undeliverable > 0) {
  raise(
    'agent_health:undeliverable_notifications',
    'normal',
    undeliverable + ' notification(s) undeliverable',
    undeliverable + ' notification(s) hit the delivery attempt limit and will not be retried.' +
      ' They are still in the notifications table; nothing was lost, but nobody was told.',
    { check: 'undeliverable', count: undeliverable },
  );
}

const summary = {
  checked_at: facts.checked_at,
  ollama_models: models === null ? null : models.length,
  stuck_runs: stuckRuns,
  agents_seen: agents.length,
  research_pending: num(facts.research_pending, 0),
  scoring_pending: num(facts.scoring_pending, 0),
  outreach_pending: num(facts.outreach_pending, 0),
  undelivered_notifications: num(facts.undelivered, 0),
  alert_count: alerts.length,
};

if (alerts.length === 0) {
  return [{ json: { healthy: true, ...summary } }];
}

return alerts.map((a) => ({ json: { healthy: false, ...a, ...summary } }));
